v1.query:
subscription MonitorMempools {
  node {
    name
    user_agent
    unconfirmed_transaction_count
    unconfirmed_transactions(
      limit: 100,
      order_by: { validated_at: desc }
    ) {
      validated_at
      transaction {
        hash
        input_count
        output_count
        output_value_satoshis
        size_bytes
      }
    }
  }
}

subscription MonitorSyncTips {
  node {
    name
    user_agent
    latest_tip: accepted_blocks(
      limit: 1
      order_by: { block_internal_id: desc }
    ) {
      accepted_at
      block {
        hash
        height
        transaction_count
        size_bytes
      }
    }
  }
}

subscription MonitorForPayments {
  search_output(
    args: {
      locking_bytecode_hex: "{76a914001b9e8d2a5e4f75f5a58cad60f33c56da7a1b8c88ac}"
    }
  ) {
    transaction_hash
    output_index
    value_satoshis
    transaction {
      node_validations {
        validated_at
        node {
          name
        }
      }
      node_validation_timeline {
        replaced_at
        validated_at
        node {
          name
        }
      }
      block_inclusions {
        block {
          hash
          height
          accepted_by {
            accepted_at
            node {
              name
            }
          }
        }
      }
    }
  }
}

query ShowDuplicateTransactions {
  transaction( where: { hash: { _in: [
    "\\x1e6ac1e5b03f122fb9e8703d2cfbf94a641a980b25ae73718eda78ff51e8bf4e"
    "\\x867e08c20a241c6179e0676e184d85ed940db7cb0c3067fbdea507df14d76fd2"
  ] } } ) {
    hash
    is_coinbase
    output_value_satoshis
    block_inclusions {
      block {
        hash
        height
        timestamp
        size_bytes
        version
        nonce
        merkle_root
        bits
        accepted_by {
          node {
            name
            user_agent
          }
        }
      }
    }
  }
}

query GetSpendingTransactions {
  output(
    where: {
      transaction_hash: {
        _eq: "\\x867e08c20a241c6179e0676e184d85ed940db7cb0c3067fbdea507df14d76fd2"
      }
      output_index: { _eq: "0" }
    }
  ) {
    transaction_hash
    output_index
    value_satoshis
    locking_bytecode_pattern
    spent_by {
      unlocking_bytecode_pattern
      outpoint_index
      transaction {
        hash
        node_validations {
          validated_at
          node {
            name
          }
        }
        node_validation_timeline {
          node {
            name
          }
          validated_at
          replaced_at
        }
        block_inclusions {
          transaction_index
          block {
            hash
            height
            accepted_by {
              accepted_at
              node {
                name
                user_agent
              }
            }
          }
        }
      }
    }
  }
}

query GetTransactionDetails {
  transaction(where: { hash: { _eq:
  "\\x867e08c20a241c6179e0676e184d85ed940db7cb0c3067fbdea507df14d76fd2"
  } } ) {
    authchains {
      authchain_length
      authhead_transaction_hash
      authhead {
        block_inclusions {
          block {
            height
          }
        }
      }
      migrations {
        migration_index
        transaction {
          hash
        }
      }
      unspent_authhead
    }
    block_inclusions {
      transaction_index
      block {
        height # etc.
      }
    }
    data_carrier_outputs {
      locking_bytecode # etc.
    }
    encoded_hex
    fee_satoshis
    hash
    identity_output {
      spent_by {
        input_index # etc.
        transaction {
          hash
        }
      }
    }
    input_count
    input_value_satoshis
    inputs {
      input_index
      outpoint_index
      outpoint_transaction_hash
      redeem_bytecode_pattern
      sequence_number
      unlocking_bytecode
      unlocking_bytecode_pattern
      value_satoshis
    }
    is_coinbase
    locktime
    node_validation_timeline {
      validated_at
      replaced_at
      node {
        name # etc.
      }
    }
    node_validations {
      validated_at
      node {
        name
      }
    }
    output_count
    output_value_satoshis
    outputs {
      locking_bytecode
      locking_bytecode_pattern
      output_index
      spent_by {
        input_index
        transaction {
          hash
        }
      }
    }
    signing_output {
      spent_by {
        input_index # etc.
        transaction {
          hash
        }
      }
    }
    size_bytes
    version
  }
}

query GenesisBlockInfo {
  block(where: { height: { _eq: "0" } }) {
    hash
    height
    header
    encoded_hex
    accepted_by {
      node {
        name
        user_agent
      }
    }
  }
}

query SearchOutputsByLockingBytecodePrefix {
  search_output_prefix(
    args: { locking_bytecode_prefix_hex: "6a142c7c8066" }
  ) {
    locking_bytecode
    output_index
    transaction_hash
    value_satoshis
    transaction {
      block_inclusions {
        block {
          hash
          height
        }
      }
    }
    spent_by {
      input_index
      transaction {
        hash
        block_inclusions {
        block {
          hash
          height
        }
      }
      }
    }
  }
}

query SearchOutputsByLockingBytecode {
  search_output(
    args: {
      locking_bytecode_hex: "{76a914001b9e8d2a5e4f75f5a58cad60f33c56da7a1b8c88ac, 76a914004e71214db4a32e208be29ba0e17484d7ecfe9888ac}"
    }
  ) {
    locking_bytecode
    output_index
    transaction_hash
    value_satoshis
    spent_by {
      input_index
      transaction {
        hash
      }
    }
  }
}

query CountCashAccountOutputs {
  search_output_prefix_aggregate(
    args: { locking_bytecode_prefix_hex: "6a142c7c8066" }
  ) {
    aggregate {
      count
    }
  }
}

query GetJonathan100CashAccount {
  search_output_prefix(
    args: { locking_bytecode_prefix_hex: "6a142c7c8066" }
    where: {
      transaction: { block_inclusions: { block: { height: { _eq: 208500 } } } }
    }
  ) {
    transaction {
      hash
      data_carrier_outputs {
        locking_bytecode
        output_index
      }
      block_inclusions {
        block {
          hash
          height
        }
      }
    }
  }
}

query GetBitjson100Authchain {
  search_output_prefix(
    args: { locking_bytecode_prefix_hex: "6a142c7c8066" }
    where: {
      transaction: { block_inclusions: { block: { height: { _eq: 208500 } } } }
    }
  ) {
    transaction {
      hash
      block_inclusions {
        block {
          hash
          height
        }
      }
      authchains {
        authchain_length
        authhead {
          hash
          identity_output {
            locking_bytecode
            value_satoshis
          }
          signing_output {
            locking_bytecode
            value_satoshis
          }
          data_carrier_outputs {
            locking_bytecode
            value_satoshis
            output_index
          }
        }
        migrations {
          migration_index
          transaction {
            hash
            encoded_hex
          }
        }
      }
    }
  }
}

query BlockchainSize {
  bchn_blocks: block_aggregate(
    where: { accepted_by: { node: { name: { _eq: "chipnet-local" } } } }
    ) {
    aggregate {
      sum {
        size_bytes
      } 
    }
  }
}

query BlockSizeStatsSince2021 {
    block_aggregate(
      where: {
        accepted_by: { node: { name: { _eq: "chipnet-local" } } }
        timestamp: { _gt: "1700000000" }
      }
    ) {
      aggregate {
        count
        max { size_bytes }
        min { size_bytes }
        avg { size_bytes }
        sum { size_bytes }
      }
    }
  }

query TransactionStats2021Q1 {
  transaction_aggregate(
    where: {
      block_inclusions: {
        block: {
          accepted_by: { node: { name: { _eq: "chipnet-local" } } }
          timestamp: { _gt: "1700000000", _lt: "1710000000" }
        }
      }
    }
  ) {
    aggregate {
      count
      max { size_bytes }
      min { size_bytes }
      avg { size_bytes }
      sum { size_bytes }
    }
  }
}
